// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile log_;

    function setUp() public {
        c = new DEP_BANK();
        log_ = new LogFile();
    }

    function testFuzz_property(uint256 amount, uint256 actorSeed) public {
        vm.assume(amount <= VALUE_CAP);
        address actor = vm.addr(uint256(keccak256(abi.encodePacked(actorSeed))) | 1);
        amount = bound(amount, 1, 1e18);

        c.SetLogFile(address(log_));
        c.SetMinSum(0);
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 beforeBal = c.balances(actor);
        uint256 totalBefore = address(c).balance;

        vm.prank(actor);
        c.Collect(amount);

        // General rule: after collecting exactly the deposited amount with MinSum=0,
        // the caller's balance must be zero (i.e., decreased by exactly `amount`).
        // The mutant adds +1, so c.balances(actor) == 1, violating the rule.
        assertTrue(c.balances(actor) == 0);
    }
}
